/**  Where the machine gets its power. */
export type PowerSource = 
/**  A mains adapter is online. */
"ac" | 
/**  There is a mains adapter and none is online. */
"battery" | 
/**  No mains adapter is listed, or it could not be read: nothing is assumed. */
"unknown";

/**  A snapshot for the UI's diagnostics. */
export type ProxyStats = ProxyStats_Serialize | ProxyStats_Deserialize;

/**  A snapshot for the UI's diagnostics. */
export type ProxyStats_Deserialize = {
	/**  Frames from the gateway. */
	frames_in: number,
	/**  Frames from the UI. */
	frames_out: number,
	/**  Deltas merged because a queue overflowed. */
	coalesced: number,
	/**  UI connections closed for being too slow. */
	slow_closed: number,
	/**  The last attach to the gateway, in milliseconds. */
	attach_ms?: number | null,
	/**  p95 of routing a gateway frame, in microseconds. */
	route_in_p95_us?: number | null,
	/**  p95 of routing a UI frame, in microseconds. */
	route_out_p95_us?: number | null,
	/**  p95 of handing a frame to the UI, in microseconds. */
	sink_p95_us?: number | null,
	/**  p95 of writing a frame to the gateway socket, in microseconds. */
	write_p95_us?: number | null,
};

/**  A snapshot for the UI's diagnostics. */
export type ProxyStats_Serialize = {
	/**  Frames from the gateway. */
	frames_in: number,
	/**  Frames from the UI. */
	frames_out: number,
	/**  Deltas merged because a queue overflowed. */
	coalesced: number,
	/**  UI connections closed for being too slow. */
	slow_closed: number,
	/**  The last attach to the gateway, in milliseconds. */
	attach_ms: number | null,
	/**  p95 of routing a gateway frame, in microseconds. */
	route_in_p95_us: number | null,
	/**  p95 of routing a UI frame, in microseconds. */
	route_out_p95_us: number | null,
	/**  p95 of handing a frame to the UI, in microseconds. */
	sink_p95_us: number | null,
	/**  p95 of writing a frame to the gateway socket, in microseconds. */
	write_p95_us: number | null,
};

/**  The short "you're set" note. */
export type Receipt = {
	/**  Plain lines: what is installed, what was changed, what to know. */
	lines: string[],
};

/**  Everything the diagnostics show: what was found, what was decided and what the web process will see. */
export type RendererReport = RendererReport_Serialize | RendererReport_Deserialize;

/**  Everything the diagnostics show: what was found, what was decided and what the web process will see. */
export type RendererReport_Deserialize = {
	/**  The session type. */
	session: Session,
	/**  The compositor is Hyprland. */
	hyprland: boolean,
	/**  The GPUs, with the driver bound to each. */
	gpus: Gpu_Deserialize[],
	/**  What `BOOPIS_RENDERER` asked for. */
	policy: Policy,
	/**  The rule that decided. */
	rule: Rule,
	/**  The variables the host set. */
	set: ([string, string])[],
	/**  Every renderer-related variable in the process environment now (set by the host or by the user). */
	environment: ([string, string])[],
	/**  `BOOPIS_RENDERER` values and the variables each sets, for the report's reader. */
	choices: ([string, string])[],
	/**  The `WebKitGTK` this process runs on: its version and whether it is the `AppImage`'s or the system's. */
	webkit: WebkitReport_Deserialize,
	/**
	 *  The frame rate: the display's rate, whether `WebKit`'s 60 fps preference is off, the power profile. Read from the
	 *  live window when the report is asked for.
	 */
	frame_rate: FrameRateReport_Deserialize,
	/**  One plain sentence when the renderer in use limits motion, else none. */
	note?: string | null,
	/**
	 *  Which GPU the webview renders on (`BOOPIS_GPU`), and why. The power source and the restart advice are read
	 *  when the report is asked for.
	 */
	gpu: GpuReport_Deserialize,
};

/**  Everything the diagnostics show: what was found, what was decided and what the web process will see. */
export type RendererReport_Serialize = {
	/**  The session type. */
	session: Session,
	/**  The compositor is Hyprland. */
	hyprland: boolean,
	/**  The GPUs, with the driver bound to each. */
	gpus: Gpu_Serialize[],
	/**  What `BOOPIS_RENDERER` asked for. */
	policy: Policy,
	/**  The rule that decided. */
	rule: Rule,
	/**  The variables the host set. */
	set: ([string, string])[],
	/**  Every renderer-related variable in the process environment now (set by the host or by the user). */
	environment: ([string, string])[],
	/**  `BOOPIS_RENDERER` values and the variables each sets, for the report's reader. */
	choices: ([string, string])[],
	/**  The `WebKitGTK` this process runs on: its version and whether it is the `AppImage`'s or the system's. */
	webkit: WebkitReport_Serialize,
	/**
	 *  The frame rate: the display's rate, whether `WebKit`'s 60 fps preference is off, the power profile. Read from the
	 *  live window when the report is asked for.
	 */
	frame_rate: FrameRateReport_Serialize,
	/**  One plain sentence when the renderer in use limits motion, else none. */
	note: string | null,
	/**
	 *  Which GPU the webview renders on (`BOOPIS_GPU`), and why. The power source and the restart advice are read
	 *  when the report is asked for.
	 */
	gpu: GpuReport_Serialize,
};

/**  Why the decision came out as it did (stable names: they go in the log and in the diagnostics). */
export type Rule = 
/**  A `WebKit` or NVIDIA switch was already in the environment; nothing is changed. */
"user_environment" | 
/**  `BOOPIS_RENDERER=default`. */
"policy_default" | 
/**  `BOOPIS_RENDERER=shm`. */
"policy_shm" | 
/**  `BOOPIS_RENDERER=cpu`. */
"policy_cpu" | 
/**  `BOOPIS_RENDERER=nosync`. */
"policy_nosync" | 
/**  `BOOPIS_RENDERER=software`. */
"policy_software" | 
/**  The display GPU is not on the NVIDIA proprietary driver: `WebKitGTK`'s own choice is known to work. */
"no_nvidia_proprietary" | 
/**
 *  NVIDIA proprietary driver on X11: the `DMABUF` renderer shows a blank window; the shared-memory transport keeps
 *  the GPU.
 */
"nvidia_x11" | 
/**
 *  NVIDIA proprietary driver on Wayland, `WebKitGTK` before 2.54.2 or of an unknown version: left alone (it starts
 *  and draws for most; the switches that cure a crash or a blank window are one variable away and the diagnostics
 *  name them).
 */
"nvidia_wayland_untouched" | 
/**
 *  NVIDIA proprietary driver on Wayland, `WebKitGTK` 2.54.2 or later: the GTK 3 explicit-sync crash is fixed
 *  upstream (`WebKit` bug 324551), so the default GL renderer is what this machine gets and no workaround is set.
 */
"nvidia_wayland_fixed" | 
/**  The session type could not be told: nothing is assumed. */
"session_unknown";

/**  The session the webview will draw into. */
export type Session = 
/**  A Wayland compositor. */
"wayland" | 
/**  An X11 server. */
"x11" | 
/**  Neither could be told. */
"unknown";

/**  What `setup_advance` answers. */
export type Status = Status_Serialize | Status_Deserialize;

/**  What `setup_advance` answers. */
export type Status_Deserialize = {
	/**  The checklist. */
	steps: Step_Deserialize[],
	/**  The question to show, if one is open. */
	form?: Form_Deserialize | null,
	/**  Every step is done, skipped or declined. */
	done: boolean,
	/**  When Hermes is missing: the documented install command (nothing was run). */
	install_command?: string | null,
	/**  Present once the flow reached its end. */
	receipt?: Receipt | null,
};

/**  What `setup_advance` answers. */
export type Status_Serialize = {
	/**  The checklist. */
	steps: Step_Serialize[],
	/**  The question to show, if one is open. */
	form: Form_Serialize | null,
	/**  Every step is done, skipped or declined. */
	done: boolean,
	/**  When Hermes is missing: the documented install command (nothing was run). */
	install_command: string | null,
	/**  Present once the flow reached its end. */
	receipt: Receipt | null,
};

/**  One line of the checklist. */
export type Step = Step_Serialize | Step_Deserialize;

/**  Where a step stands. */
export type StepState = 
/**  Not reached yet. */
"pending" | 
/**  Done (or already was). */
"done" | 
/**  Waiting for the user's answer to the open form. */
"needs_input" | 
/**  Stopped; `code` and `detail` say why and what to do. */
"blocked" | 
/**  The user declined; the detail says what will not work. */
"declined" | 
/**  Left out on purpose; the detail says what it costs. */
"skipped";

/**  One line of the checklist. */
export type Step_Deserialize = {
	/**  `hermes`, `plugin`, `hx`, `config`, `models`, `restart` or `receipt`. */
	id: string,
	/**  The label. */
	title: string,
	/**  The state. */
	state: StepState,
	/**  What happened, or what is needed. */
	detail: string,
	/**  A stable `hx.setup.*` code when blocked. */
	code?: string | null,
};

/**  One line of the checklist. */
export type Step_Serialize = {
	/**  `hermes`, `plugin`, `hx`, `config`, `models`, `restart` or `receipt`. */
	id: string,
	/**  The label. */
	title: string,
	/**  The state. */
	state: StepState,
	/**  What happened, or what is needed. */
	detail: string,
	/**  A stable `hx.setup.*` code when blocked. */
	code: string | null,
};

/**  Where the loaded `libwebkit2gtk` lives. */
export type WebkitOrigin = 
/**  Inside the `AppImage`'s mount: the copy the release carries. */
"bundled" | 
/**  The system's: the distribution's package. */
"system" | 
/**  No `libwebkit2gtk` in the memory map (not Linux, or the map could not be read). */
"unknown";

/**  Why the feature API was not used. Every one is a refusal made before anything was called. */
export type WebkitRefusal = 
/**  The runtime version could not be read, so the API's presence cannot be known. */
"version_unknown" | 
/**  `WebKitGTK` older than 2.42: the functions do not exist. */
"too_old" | 
/**  A symbol the API needs is not in the loaded library (a build that left it out). */
"symbols_missing" | 
/**  The feature list has no feature with that identifier. */
"no_such_feature" | 
/**  The call ran and reading the feature back did not give the asked value. */
"not_applied" | 
/**  There is no web view to ask (not Linux, or no window yet). */
"no_webview";

/**  The `WebKitGTK` part of the diagnostics report. */
export type WebkitReport = WebkitReport_Serialize | WebkitReport_Deserialize;

/**  The `WebKitGTK` part of the diagnostics report. */
export type WebkitReport_Deserialize = {
	/**  `2.54.2`, or none when it could not be read. */
	version?: string | null,
	/**  Bundled (`AppImage`) or the system's. */
	origin: WebkitOrigin,
	/**  The path of the loaded `libwebkit2gtk`. */
	library?: string | null,
};

/**  The `WebKitGTK` part of the diagnostics report. */
export type WebkitReport_Serialize = {
	/**  `2.54.2`, or none when it could not be read. */
	version: string | null,
	/**  Bundled (`AppImage`) or the system's. */
	origin: WebkitOrigin,
	/**  The path of the loaded `libwebkit2gtk`. */
	library: string | null,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}
